-- ============================================================================
-- VideoWeb Center — Schema PostgreSQL / Supabase + Políticas RLS + Seed Completo
-- Sincronizado com o portfólio de marcas e produtos da VideoWeb Center.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  image_url TEXT NOT NULL,
  display_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.brands (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  country TEXT NOT NULL,
  specialty TEXT NOT NULL,
  authorized_status TEXT NOT NULL,
  description TEXT NOT NULL,
  image_url TEXT NOT NULL DEFAULT '/src/assets/images/prod_cinema_camera_1795521924293.jpg'
);

ALTER TABLE public.brands
  ADD COLUMN IF NOT EXISTS image_url TEXT NOT NULL DEFAULT '/src/assets/images/prod_cinema_camera_1795521924293.jpg';

CREATE TABLE IF NOT EXISTS public.products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  sku TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  short_description TEXT NOT NULL,
  full_description TEXT NOT NULL,
  category_id BIGINT NOT NULL REFERENCES public.categories(id) ON DELETE RESTRICT,
  brand_id BIGINT NOT NULL REFERENCES public.brands(id) ON DELETE RESTRICT,
  price_brl DOUBLE PRECISION,
  availability TEXT NOT NULL DEFAULT 'Pronta Entrega',
  featured BOOLEAN NOT NULL DEFAULT FALSE,
  image_url TEXT NOT NULL,
  specs_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  in_box_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  warranty_months INTEGER NOT NULL DEFAULT 24,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_products_category ON public.products(category_id);
CREATE INDEX IF NOT EXISTS idx_products_brand ON public.products(brand_id);
CREATE INDEX IF NOT EXISTS idx_products_featured ON public.products(featured);

CREATE TABLE IF NOT EXISTS public.quotes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  protocol TEXT NOT NULL UNIQUE,
  customer_name TEXT NOT NULL,
  company_name TEXT NOT NULL,
  document_id TEXT NOT NULL DEFAULT '',
  email TEXT NOT NULL,
  phone TEXT NOT NULL,
  project_type TEXT NOT NULL,
  timeline TEXT NOT NULL,
  notes TEXT NOT NULL DEFAULT '',
  items_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  status TEXT NOT NULL DEFAULT 'Novo',
  admin_notes TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.admin_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================================
-- Políticas de Segurança em Nível de Linha (Row Level Security - RLS)
-- ============================================================================

ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.brands ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.admin_settings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read categories" ON public.categories;
CREATE POLICY "Public read categories" ON public.categories
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public read brands" ON public.brands;
CREATE POLICY "Public read brands" ON public.brands
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public read products" ON public.products;
CREATE POLICY "Public read products" ON public.products
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "No anon access quotes" ON public.quotes;
DROP POLICY IF EXISTS "No anon access admin_settings" ON public.admin_settings;

-- ============================================================================
-- Seed Idempotente (Categorias, 37 Marcas com Fotos e Catálogo Completo)
-- ============================================================================

