  ('audio-profissional', 'Áudio & Consoles Digitais', 'Microfones sem fio UHF, gravadores multipista, consoles digitais AoIP, sistemas de conferência e captação broadcast.', '/src/assets/images/brand_audio_console_mics_1795524447880.jpg', 7),
