INSERT INTO public.products (
  slug, sku, name, short_description, full_description,
  category_id, brand_id, price_brl, availability, featured,
  image_url, specs_json, in_box_json, warranty_months
)
SELECT
  v.slug, v.sku, v.name, v.short_description, v.full_description,
  c.id, b.id, v.price_brl, v.availability, v.featured,
  v.image_url, v.specs_json::jsonb, v.in_box_json::jsonb, v.warranty_months
FROM (
  VALUES
    ('blackmagic-pyxis-6k-ef', 'VW-BM-PYX6K', 'Blackmagic PYXIS 6K Cinema Box Camera (EF)', 'Câmera cinema digital Full-Frame 6K em chassi box modular com Blackmagic RAW 12-bit.', 'Presente no catálogo oficial VideoWeb Center, a Blackmagic PYXIS 6K oferece sensor Full-Frame 36×24 mm de 6048×4032 com 13 stops de alcance dinâmico, Dual Native ISO até 25.600 e múltiplas roscas de rigging em um corpo cubo altamente customizável para cinema, estúdio e estabilizadores.', 'cameras-cinema', 'blackmagic', NULL::double precision, 'Pronta Entrega', TRUE, '/src/assets/images/prod_cinema_camera_1795521924293.jpg', '[{"label":"Sensor","value":"Full-Frame CMOS 6K (36 × 24 mm)"},{"label":"Montagem","value":"Canon EF (também disponível em PL e L-Mount)"},{"label":"Gravação","value":"Blackmagic RAW 12-bit + Proxy H.264 em Dual CFexpress Type B"},{"label":"Saídas","value":"12G-SDI 10-bit + USB-C para SSD externo + Ethernet 10G"}]', '["Corpo Blackmagic PYXIS 6K","Tampa de proteção do sensor","Placa SSD / Montagem lateral","Fonte AC 12V com adaptadores"]', 12),
    ('sony-pxw-z200-xdcam-4k', 'VW-SN-PXWZ200', 'Sony PXW-Z200 4K 1" CMOS XDCAM Camcorder', 'Filmadora broadcast XDCAM 4K 60p com zoom óptico 20x, 12G-SDI, foco IA e streaming integrado.', 'A Sony PXW-Z200 combina sensor Exmor RS CMOS de 1.0 polegada com processador BIONZ XR e unidade de reconhecimento por IA para rastreamento preciso de sujeitos. Ideal para jornalismo, produções corporativas e cobertura ao vivo com saída 12G-SDI, HDMI e Wi-Fi/Ethernet.', 'cameras-cinema', 'sony', NULL::double precision, 'Pronta Entrega', TRUE, '/src/assets/images/prod_cinema_camera_1795521924293.jpg', '[{"label":"Sensor","value":"1.0\" Exmor RS CMOS 4K UHD até 60p (4:2:2 10-bit)"},{"label":"Lente Integrada","value":"Zoom óptico G Lens 20x (24–480mm eq.) + Clear Image Zoom"},{"label":"Conectividade","value":"12G/6G/3G-SDI, HDMI Tipo A, TC In/Out, 2× XLR"},{"label":"Filtro ND","value":"ND Variável Eletrônico (1/4 a 1/128)"}]', '["Camcorder Sony PXW-Z200","Para-sol e ocular LCD","Bateria BP-U35 e carregador BC-U1A","Suporte de microfone e cabo AC"]', 24),
    ('hollyland-pyro-7-transceiver-kit', 'VW-HL-PYRO7K', 'Hollyland Pyro 7 Wireless Transceiver Monitor Kit (Set of Two)', 'Kit com dois monitores transceptores 7" 1200 nits SDI/HDMI com transmissão Dual-Band 2.4/5 GHz até 400m.', 'Solução oficial Hollyland na VideoWeb Center que unifica monitor de direção de 7 polegadas com transmissão e recepção sem fio de vídeo até 400 metros em Dual-Band Auto-Hopping, permitindo até 4 receptores simultâneos e gravação em cartão SD.', 'transmissao-ip', 'hollyland', NULL::double precision, 'Pronta Entrega', TRUE, '/src/assets/images/brand_wireless_encoder_streaming_1795524445919.jpg', '[{"label":"Tela","value":"2× Monitores Touch 7\" 1200 nits"},{"label":"Interfaces","value":"HDMI 1.4b In/Out + 3G-SDI In/Out em cada unidade"},{"label":"Alcance & Latência","value":"Até 400 m (1300 ft) com latência de ~60 ms"},{"label":"Bandas","value":"2.4 GHz + 5 GHz Dual-Band Auto Frequency Hopping"}]', '["2× Monitores Hollyland Pyro 7","4× Antenas Paddle + Case rígido","Alças de ombro e cabos D-Tap para DC"]', 12),
    ('datavideo-ptc-305-4k-ptz', 'VW-DV-PTC305', 'Datavideo PTC-305 4K PTZ Camera com Auto Tracking', 'Câmera PTZ 4K60 com zoom óptico 20x, rastreamento automático inteligente, SDI, HDMI, NDI|HX e PoE+.', 'Disponível na VideoWeb Center, a Datavideo PTC-305 entrega captura 4K 50/60p com rastreamento automático de apresentadores diretamente embarcado na câmera, dispensando servidores externos. Oferece saídas simultâneas 3G-SDI, HDMI 2.0, HDBaseT/NDI (conforme versão) e tally integrado.', 'cameras-ptz-pov', 'datavideo', NULL::double precision, 'Pronta Entrega', TRUE, '/src/assets/images/brand_ptz_broadcast_camera_1795524444970.jpg', '[{"label":"Resolução & Sensor","value":"1/1.8\" CMOS · Até 4K UHD 60fps"},{"label":"Zoom Óptico","value":"20x Óptico (FOV horizontal de até 60°)"},{"label":"Saídas de Vídeo","value":"HDMI 2.0 + 3G-SDI + Streaming IP RTSP/RTMP/SRT"},{"label":"Alimentação","value":"DC 12V ou PoE+ (IEEE 802.3at)"}]', '["Câmera Datavideo PTC-305","Controle remoto IR e suporte de teto","Fonte DC 12V e cabo de segurança"]', 24),
    ('liveu-lu300s-5g-field-unit', 'VW-LU-300S', 'LiveU LU300S Encoder Field Unit (4× Modems 4G/5G)', 'Encoder portátil 4K 10-bit HDR com bonding LRT em 4 modems internos 5G/4G + Wi-Fi + Ethernet.', 'Unidade de campo compacta LiveU para transmissões jornalísticas, esportivas e corporativas de alta criticidade. Agrega até 6 conexões simultâneas via protocolo LRT garantindo estabilidade mesmo em locais de alta congestão de rede celular.', 'transmissao-ip', 'liveu', NULL::double precision, 'Sob Encomenda', TRUE, '/src/assets/images/brand_wireless_encoder_streaming_1795524445919.jpg', '[{"label":"Entradas de Vídeo","value":"12G-SDI + HDMI 2.0 (até 4Kp60 10-bit HDR)"},{"label":"Canais de Bonding","value":"Até 6 links (4× modems 5G/4G internos + Wi-Fi + LAN)"},{"label":"Latência","value":"Ultra baixa até 0.5 segundo ponto a ponto"},{"label":"Peso","value":"Apenas 900g com bateria interna de 3 horas"}]', '["Unidade LiveU LU300S","Mochila / Bolsa de campo ergonômica","Fonte AC e antenas internas integradas"]', 12),
